// Independent muon DATA fit constraints applied to a frozen electron hit cohort.
// Diagnostic recalibration only: no digitizer rerun and no production edits.
#define DIGITIZATION_IMPACT_REVIEW_NO_MAIN
#include "DigitizationImpactReview.cc"
#include <TProfile.h>
namespace muon_calibration {
struct Table {
 std::ifstream input;std::map<std::string,size_t>columns;
 explicit Table(const fs::path&p):input(p){need(bool(input),"Missing table "+p.string());std::string l;need(bool(std::getline(input,l)),"Empty table");auto h=fields(l);for(size_t i=0;i<h.size();++i)columns[h[i]]=i;}
 bool next(std::vector<std::string>&row){std::string l;if(!std::getline(input,l))return false;row=fields(l);need(row.size()==columns.size(),"Malformed table row");return true;}
 const std::string&at(const std::vector<std::string>&r,const std::string&n)const{return r.at(columns.at(n));}
 double number(const std::vector<std::string>&r,const std::string&n)const{return std::stod(at(r,n));}
};
struct MuFit{bool valid=false,stable=false;double ratio=NAN,error=NAN,neff=NAN,landau=NAN,gauss=NAN,mpv=NAN;std::string status;};
using MuKey=std::tuple<int,int>;
std::map<MuKey,MuFit>readMuon(const fs::path&base){need(fs::exists(base/"COMPLETE"),"Muon result is incomplete");std::map<MuKey,MuFit>out;Table fits(base/"fits.tsv");std::vector<std::string>r;
 while(fits.next(r)){if(fits.at(r,"geometry_condition")!="unmatched"||fits.at(r,"stage")!="temperature_adc"||std::abs(fits.number(r,"plateau_sigmas")-3)>1e-9)continue;int s=fits.at(r,"sample")=="mc",id=int(fits.number(r,"CellID"));MuFit f;f.status=fits.at(r,"status");f.valid=f.status=="ok";f.ratio=fits.number(r,"normalized_MPV");f.mpv=fits.number(r,"Landau_MPV");f.error=fits.number(r,"MPV_error")/f.mpv;f.neff=fits.number(r,"fit_effective_hits");f.landau=fits.number(r,"Landau_width")/f.mpv;f.gauss=fits.number(r,"Gaussian_sigma")/f.mpv;need(out.emplace(MuKey{id,s},f).second,"Duplicate muon fit row");}
 Table stable(base/"plateau_stability.tsv");while(stable.next(r))if(stable.at(r,"geometry_condition")=="unmatched"){MuKey k{int(stable.number(r,"CellID")),stable.at(r,"sample")=="mc"};need(out.count(k),"Stability fit missing");out.at(k).stable=stable.number(r,"stable_within_3percent")!=0;}return out;
}
bool accepted(const MuFit&f){return f.valid&&f.stable&&std::isfinite(f.ratio)&&f.ratio>0&&std::isfinite(f.error)&&f.error>0&&f.error<=.05&&f.neff>=100;}
int type(int id,const Parameter&p){return(group(id)?0:2)+int(p.mipFallback);}
const std::array<std::string,4>typeName={"10um_individual","10um_fallback","15um_individual","15um_fallback"};
struct Electron{Record record;std::array<double,2>energy{};double hits=0,knownEnergy=0,knownHits=0;std::array<double,4>typeEnergy{},knownTypeEnergy{},typeHits{},knownTypeHits{};};
std::vector<Electron>collect(const std::vector<Record>&records,const std::map<int,std::string>&files,const std::map<int,Parameter>&pars,const std::set<int>&bad,const std::map<int,double>&ratios,std::ostream&validation,const std::string&sample,int beam){std::vector<Electron>out;std::map<int,std::vector<Record>>byfile;for(auto&r:records)if(selected(r,2)&&files.count(r.file))byfile[r.file].push_back(r);
 for(auto&[fi,events]:byfile){auto file=checked(files.at(fi));CalReader c(*file);double maxE=0,maxN=0;long long totalHits=0;for(auto&r:events){c.read(r.entry);need(c.time==r.time&&c.event==r.event,"Electron event identity mismatch");Electron x;x.record=r;
 for(size_t j=0;j<c.id->size();++j){int id=physical(c.id->at(j));double v=c.e->at(j)/1000;if(!connected(id)||bad.count(id)||v<0)continue;need(std::isfinite(v),"Nonfinite energy");int t=type(id,pars.at(id));x.energy[0]+=v;x.typeEnergy[t]+=v;++x.hits;++x.typeHits[t];++totalHits;auto q=ratios.find(id);bool known=q!=ratios.end();x.energy[1]+=known?v/q->second:v;if(known){x.knownEnergy+=v;++x.knownHits;x.knownTypeEnergy[t]+=v;++x.knownTypeHits[t];}}
 maxE=std::max(maxE,std::abs(x.energy[0]-r.energy));maxN=std::max(maxN,std::abs(x.hits-r.hits));need(maxE<1e-9&&maxN==0,"Frozen electron energy/hit closure failed");out.push_back(x);}validation<<beam<<'\t'<<sample<<'\t'<<fi<<'\t'<<events.size()<<'\t'<<totalHits<<'\t'<<maxE<<'\t'<<maxN<<"\t1\n";}return out;
}
Values energies(const std::vector<Electron>&v,int q){Values out;for(auto&e:v)out.push_back(e.energy[q]);return out;}
std::vector<Record>recs(const std::vector<Electron>&v){std::vector<Record>out;for(auto&e:v)out.push_back(e.record);return out;}
double closure(const Values&d,const Values&m,const Values&bd,const Values&bm){double gap=std::pow(rms(bd),2)-std::pow(rms(bm),2);return gap>0?1-(std::pow(rms(d),2)-std::pow(rms(m),2))/gap:NAN;}
}
